import { test, expect } from '@playwright/test';
import { apiClient } from '../client/apiClient';

export const criterionId = "C-CREATE-ARTICLE";

test("create an article as an authenticated user", async () => {
  const uniqueSuffix = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const requestBody = {
    "article": {
      "title": `Spec2Test pilot article ${uniqueSuffix}`,
      "description": "Exercises real JWT auth and the article-ownership rule.",
      "body": "Generated by runner/'s step-3 fixtures, not the LLM.",
      "tagList": [
        "spec2test",
      ],
    },
  };
  const { status, body } = await apiClient.request("POST", "/api/articles", { body: requestBody, auth: "user" });

  await test.step("assertion: status_201", async () => {
    expect(status === 201).toBeTruthy();
  });
  await test.step("assertion: has_slug", async () => {
    expect(body.article.slug).toBeTruthy();
  });
});
